package com.jeshwin.crashlab;
import java.io.*; import java.time.Duration; import java.util.*; import java.util.concurrent.*;
import org.apache.kafka.clients.consumer.KafkaConsumer; import org.apache.kafka.common.TopicPartition;
public final class CrashConsumer {
 private CrashConsumer(){}
 public static void main(String[] a)throws Exception{if(a.length==6)run(a[0],a[1],a[2],a[3],"db-first",Boolean.parseBoolean(a[4])?"after-db-commit":"none",a[5],false);else if(a.length==8)run(a[0],a[1],a[2],a[3],a[4],a[5],a[6],Boolean.parseBoolean(a[7]));else throw new IllegalArgumentException("Usage: topic group event account strategy barrier runId observe");}
 static void run(String topic,String group,String event,String account,String strategy,String barrier,String run,boolean observe)throws Exception{
  Properties p=new Properties();p.put("bootstrap.servers",LabConfig.kafkaBootstrap());p.put("group.id",group);p.put("enable.auto.commit","false");p.put("auto.offset.reset","none");p.put("max.poll.records","1");p.put("default.api.timeout.ms","15000");p.put("request.timeout.ms","10000");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.StringDeserializer");TopicPartition tp=new TopicPartition(topic,0);
  try(var c=new KafkaConsumer<String,String>(p)){c.assign(List.of(tp));var base=c.committed(Set.of(tp),Duration.ofSeconds(15)).get(tp);if(base==null)throw new IllegalStateException("Missing initialized offset");c.seek(tp,base.offset());mark("START",run,event,strategy,"start",tp,base.offset());long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(observe?5:45);while(System.nanoTime()<until){var rs=c.poll(Duration.ofMillis(500));if(rs.isEmpty())continue;if(observe)throw new IllegalStateException("Unexpected record during bounded observation");var r=rs.iterator().next();EventValidator.validate(r.key(),r.value(),event,account);
   if(strategy.equals("offset-first")){c.commitSync(rs.nextOffsets(),Duration.ofSeconds(15));mark("OFFSET_COMMITTED",run,event,strategy,"after-offset-commit",tp,r.offset());if(barrier.equals("after-offset-commit"))barrier(run,event,strategy,barrier,tp,r.offset());}
   var work=DatabaseWork.begin(strategy,event,account);if(barrier.equals("before-db-commit"))barrier(run,event,strategy,barrier,tp,r.offset());work.connection().commit();work.connection().close();mark("DB_COMMITTED",run,event,strategy,"after-db-commit",tp,r.offset());if(barrier.equals("after-db-commit"))barrier(run,event,strategy,barrier,tp,r.offset());if(!strategy.equals("offset-first")){c.commitSync(rs.nextOffsets(),Duration.ofSeconds(15));mark("OFFSET_COMMITTED",run,event,strategy,"after-offset-commit",tp,r.offset());}if(barrier.equals("after-both-commits"))barrier(run,event,strategy,barrier,tp,r.offset());return;}
   if(observe){mark("NO_RECORD_OBSERVED",run,event,strategy,"bounded-empty-poll",tp,base.offset());return;}throw new IllegalStateException("Timed out waiting for fixture event");}
 }
 static void mark(String t,String run,String event,String strategy,String phase,TopicPartition tp,long off){System.out.println(t+" timestamp="+System.currentTimeMillis()+" runId="+run+" strategy="+strategy+" eventId="+event+" phase="+phase+" partition="+tp.partition()+" offset="+off);System.out.flush();}
 static void barrier(String run,String event,String strategy,String phase,TopicPartition tp,long off)throws Exception{mark("BARRIER",run,event,strategy,phase,tp,off);var e=Executors.newSingleThreadExecutor();try{String v=e.submit(()->new BufferedReader(new InputStreamReader(System.in)).readLine()).get(60,TimeUnit.SECONDS);if(!"CONTINUE".equals(v))throw new IllegalStateException("Barrier closed without CONTINUE");}finally{e.shutdownNow();}}
}
